            ${DATA.os_list.map(o => `<td class="num">$ ${fmt(p["IMP_"+o])}</td>`).join("")}
            <td class="num" style="color:var(--warn)">$ ${fmt(p.IMP_SIN_ASIGNACION)}</td>
            <td class="num"><strong>$ ${fmt(p.IMPORTE)}</strong></td>
        </tr>`).join("");
